#!/usr/bin/env python3
"""Update reviewed public website layout and motion files; never restart services."""
import base64
import hashlib
import json
import os
from pathlib import Path
import shutil
import stat
import subprocess
import sys
import tempfile
import time
import zlib

BASE = Path('/opt/outdoor-fit/production')
WEB = BASE / 'releases/public-website-20260928-v1/website'
CADDY = 'outdoor-fit-production-caddy-1'
ASSET_NAME = 'assets/cindy-li-cutout.png'
HTML_FILES = ('404.html', '404/index.html', 'resources/index.html',
              'resources/research-1/index.html', 'resources/research-2/index.html', 'index.html')
RESOURCE_FILES = (ASSET_NAME, 'layout.css', 'site.css', 'site.js')
FILE_ORDER = RESOURCE_FILES + HTML_FILES
MAY_CREATE = {ASSET_NAME, 'layout.css'}
REFERENCE_SHA256 = 'd74f8e2943f5a024c6e85dea7ce0c4bba5f1c2ae2cb7d04db2849b0e4055b381'
PROFESSOR = b'https://www.polyu.edu.hk/comp/people/academic-staff/prof-ng-hiu-fung-peter/'
# Reviewed final files are embedded below; only known v1/profile-patched hashes are accepted.
PARTNER_URLS = ['https://www.polyu.edu.hk/tc/about-polyu/', 'https://www.twc.edu.hk/tc/twc/About_TWC/vision_and_mission', 'https://www.feinberg.northwestern.edu/about/index.html', 'https://www.hkcc-polyu.edu.hk/tc/about-hkcc/college-overview/index.html', 'https://www.hkpfa.org.hk/CP/pG/2/1/6']
PAYLOADS = {'assets/cindy-li-cutout.png': {'acceptedSha256': ['ae6866da27f9408cac9781fbf46a69ff128be2a57931eb2d207490ce13f7f7c2'], 'sha256': 'ae6866da27f9408cac9781fbf46a69ff128be2a57931eb2d207490ce13f7f7c2', 'data': ''}, 'layout.css': {'acceptedSha256': [], 'sha256': '9a7d226adc164e1693a80e8ed0f20fbdcfb1905aaf05e061ee7a741199fb2d9c', 'data': ''}, 'site.css': {'acceptedSha256': ['aa887615fdfddfd3487228f8def21817d47914bb088652ff4feb14f4913cbf57', 'bb0dbbabebf41bfe4983d317daac2daabee580fff0fd2c2b73fb142be0629f22', '9467df627ec0d08bed6842d41dedf5e3c90ac0bf8b5835a6b37c0e65b59ba884'], 'sha256': '9467df627ec0d08bed6842d41dedf5e3c90ac0bf8b5835a6b37c0e65b59ba884', 'data': ''}, 'site.js': {'acceptedSha256': ['22278c85441298d2df511de391b31c68377088eaa2a3451439e9bed0b1241224'], 'sha256': 'cca4c2519c3f762c2ab18329fa1655448023efe886da7fc75e5a18dcabf6b842', 'data': ''}, '404.html': {'acceptedSha256': ['66e60ce494e93f533a82ebc620550ef36fa4eb2029a7cd4560389d348eb89fa8'], 'sha256': '84dd34ad83b1a9bcb4cfb87cde80c26cc23915d9bc9fa9431436b19ccece7e33', 'data': ''}, '404/index.html': {'acceptedSha256': ['66e60ce494e93f533a82ebc620550ef36fa4eb2029a7cd4560389d348eb89fa8'], 'sha256': '84dd34ad83b1a9bcb4cfb87cde80c26cc23915d9bc9fa9431436b19ccece7e33', 'data': ''}, 'resources/index.html': {'acceptedSha256': ['c70e6652e0959bcc7e55559fade1f2e44e9873c182b0dfb6d9dad17de8db70b9'], 'sha256': '89cd2b106b631db845dc58a6db60443f69c24264fa76e994bfee4cd83b2dd3f1', 'data': ''}, 'resources/research-1/index.html': {'acceptedSha256': ['2d6fb7a77172caaa8507d1ff2b98101fcfb48471658f0e5d741d4d72ec01e5a5'], 'sha256': 'cdf69e6e089ac222f2ff51c072b64ac55adcf92ae1c948c8ea5e3afe9dc0c6b0', 'data': ''}, 'resources/research-2/index.html': {'acceptedSha256': ['951ac7b3fd82de7c92269704035dafd06e08f0ad71c619795843adddbd976745'], 'sha256': 'fd4825f4c692c8706c86034829708af179d97c5d5e427db30b2fad6ac02aedf8', 'data': ''}, 'index.html': {'acceptedSha256': ['864de7e4e48faefd7fc3da9c8bfe6ba132bcae854e0f51c081c3071c89c30cd1', '0b8481adcca546be80e1068b9d7f5762ab56dc95e037f3e4713b1f924d63c3ef', '845f418f3d451070a97b3049038e234ab5a4b4caf3b8f13928552e26c22ddf86', '88b74e3f5832c7d3e998e36b97e4b656276e7ebab10a4d543a8ce47bac1b0bbb', '1ffe7aa136f6c23a3d293240175ff6d8e01b4a673f05ca5f0feffed7f5225f9a'], 'sha256': 'a7cd8198ff74676e7044a64c6efb8a7e016467f752a25fe9c2847eb83a722eb6', 'data': ''}}


def require(ok, code):
    if not ok:
        raise RuntimeError(code)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def run(args):
    result = subprocess.run(args, capture_output=True, timeout=20)
    require(result.returncode == 0, 'WEBSITE_COMMAND_FAILED')
    return result.stdout


def decode_payloads():
    require(set(PAYLOADS) == set(FILE_ORDER) and len(PARTNER_URLS) == 5,
            'WEBSITE_PAYLOAD_INCOMPLETE')
    result = {}
    for name, item in PAYLOADS.items():
        data = zlib.decompress(base64.b64decode(item['data'], validate=True))
        require(sha(data) == item['sha256'], 'WEBSITE_PAYLOAD_HASH_MISMATCH')
        result[name] = data
    for name in HTML_FILES:
        require(b'href="/layout.css?v=20261009"' in result[name]
                and b'src="/site.js?v=20261009"' in result[name],
                'WEBSITE_LAYOUT_REFERENCES_MISSING')
    page = result['index.html']
    require(page.count(b'href="' + PROFESSOR + b'"') == 2, 'WEBSITE_PROFESSOR_COUNT_INVALID')
    for url in PARTNER_URLS:
        require(page.count(('href="' + url + '"').encode()) == 1, 'WEBSITE_PARTNER_COUNT_INVALID')
    require(page.count(('src="/' + ASSET_NAME + '"').encode()) == 1
            and '李欣迪'.encode() in page and '李欣迪教授'.encode() not in page
            and '香港大學<br/>社會工作及社會行政學系'.encode() in page,
            'WEBSITE_NEW_COLLABORATOR_INVALID')
    return result


def atomic_write(path, data, metadata, restore_time=False):
    descriptor, temporary = tempfile.mkstemp(prefix='.website-layout-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chown(temporary, metadata.st_uid, metadata.st_gid)
        shutil.copystat(path, temporary, follow_symlinks=False)
        os.chmod(temporary, stat.S_IMODE(metadata.st_mode))
        os.utime(temporary, ns=(metadata.st_atime_ns,
                               metadata.st_mtime_ns if restore_time else time.time_ns()))
        os.replace(temporary, path)
        if hasattr(os, 'O_DIRECTORY'):
            directory = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def create_resource(path, data, metadata):
    """Publish an absent file without ever replacing a concurrent/unknown file."""
    descriptor, temporary = tempfile.mkstemp(prefix='.website-resource-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.chown(temporary, metadata.st_uid, metadata.st_gid)
        os.chmod(temporary, 0o644)
        # A hard link creates the final name atomically and refuses an existing name.
        os.link(temporary, path)
        info = path.stat()
        return info.st_dev, info.st_ino
    finally:
        try:
            os.unlink(temporary)
        except OSError:
            pass


def checked_path(web, name):
    require(name in set(FILE_ORDER) | {'reference.css'}, 'WEBSITE_PATH_NOT_ALLOWED')
    root = web.resolve()
    parent = web
    for part in Path(name).parts[:-1]:
        parent = parent / part
        require(parent.is_dir() and not parent.is_symlink(), 'WEBSITE_PARENT_DIRECTORY_INVALID')
    require(parent.resolve() == root or root in parent.resolve().parents, 'WEBSITE_PATH_OUTSIDE_ROOT')
    path = web / name
    require(not path.is_symlink(), 'WEBSITE_SYMLINK_REJECTED')
    return path


def resource_url(name):
    if name == 'index.html':
        return '/'
    if name.endswith('/index.html'):
        return '/' + name[:-len('index.html')]
    return '/' + name + ('?v=20261009' if name in {'layout.css', 'site.js'} else '')


def update(web, backup_parent, verify):
    desired = decode_payloads()
    reference = checked_path(web, 'reference.css')
    require(reference.is_file() and sha(reference.read_bytes()) == REFERENCE_SHA256,
            'WEBSITE_REFERENCE_CSS_CHANGED')
    before, metadata = {}, {}
    for name in FILE_ORDER:
        path = checked_path(web, name)
        if name in MAY_CREATE and not path.exists():
            before[name], metadata[name] = None, None
            continue
        require(path.is_file() and not path.is_symlink() and path.stat().st_nlink == 1,
                'WEBSITE_FILE_NOT_REGULAR')
        metadata[name] = path.stat()
        before[name] = path.read_bytes()
        require(sha(before[name]) in PAYLOADS[name]['acceptedSha256'] + [PAYLOADS[name]['sha256']],
                'WEBSITE_UNKNOWN_EXISTING_FILE_' + name.replace('.', '_').upper())
    changes = [name for name in FILE_ORDER if before[name] != desired[name]]
    if not changes:
        verify(desired)
        print('WEBSITE_UPDATE=ALREADY_CURRENT')
        return
    require(backup_parent.is_dir() and not backup_parent.is_symlink(), 'WEBSITE_BACKUP_PARENT_INVALID')
    backup = Path(tempfile.mkdtemp(prefix='website-layout-20261009-', dir=backup_parent))
    backup.chmod(0o700)
    for name, data in before.items():
        saved = backup / (name + ('.absent' if data is None else '.before'))
        saved.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        data = b'File did not exist before this update.\n' if data is None else data
        saved.write_bytes(data)
        saved.chmod(0o600)
    print('WEBSITE_BACKUP_DIR=' + str(backup), flush=True)
    touched, created = [], {}
    try:
        for name in changes:
            path = checked_path(web, name)
            if before[name] is None:
                created[name] = create_resource(path, desired[name], metadata['index.html'])
                touched.append(name)
                continue
            require(path.read_bytes() == before[name] and path.stat().st_ino == metadata[name].st_ino,
                    'WEBSITE_CONCURRENT_EDIT_DETECTED')
            touched.append(name)
            atomic_write(path, desired[name], metadata[name])
        verify(desired)
    except BaseException:
        restored = True
        for name in reversed(touched):
            try:
                path = checked_path(web, name)
                current = path.read_bytes()
                if before[name] is None:
                    info = path.stat()
                    if (current == desired[name] and not path.is_symlink()
                            and (info.st_dev, info.st_ino) == created[name]):
                        path.unlink()
                    else:
                        restored = False
                elif current == desired[name]:
                    atomic_write(path, before[name], metadata[name], restore_time=True)
                elif current != before[name]:
                    restored = False
            except BaseException:
                restored = False
        print('WEBSITE_ROLLBACK=' + ('COMPLETE' if restored else 'NEEDS_REVIEW_NO_OVERWRITE'), flush=True)
        raise
    print('WEBSITE_UPDATED_FILES=' + ','.join(changes)
          + '\nWEBSITE_VERIFIED_FILES=10\nWEBSITE_SERVED_FILES=PASS\nWEBSITE_UPDATE=PASS',
          flush=True)


def main():
    import fcntl
    os.umask(0o077)
    require(os.geteuid() == 0, 'WEBSITE_ROOT_REQUIRED')
    require(WEB.is_dir() and WEB.resolve() == WEB, 'WEBSITE_RELEASE_PATH_CHANGED')
    live = json.loads(run(['docker', 'inspect', CADDY]))[0]
    require(live['State']['Running'], 'WEBSITE_CADDY_NOT_RUNNING')
    mounts = [item for item in live['Mounts'] if item['Destination'] == '/srv/website']
    require(len(mounts) == 1 and mounts[0]['Type'] == 'bind' and mounts[0]['Source'] == str(WEB)
            and mounts[0]['RW'] is False, 'WEBSITE_WEBSITE_MOUNT_CHANGED')

    def verify(expected):
        for name, data in expected.items():
            resource = resource_url(name)
            served = run(['docker', 'exec', CADDY, 'wget', '-q', '-O', '-',
                          '--header=Host: outdoorfit.hk', 'http://127.0.0.1:8099' + resource])
            require(sha(served) == sha(data), 'WEBSITE_SERVED_FILE_MISMATCH')

    with (BASE / '.public-website.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        update(WEB, BASE / '.update-state', verify)


if __name__ == '__main__':
    try:
        main()
    except RuntimeError as error:
        print(str(error), file=sys.stderr)
        sys.exit(1)
    except (Exception, KeyboardInterrupt):
        print('WEBSITE_UPDATE_FAILED_NO_SECRETS_LOGGED', file=sys.stderr)
        sys.exit(1)
